// Solvable maze
maze_footprint = 260;          // [120:20:600]
maze_cells = 8;                // [3:1:16]
maze_wall_height = 28;         // [5:1:80]
maze_wall_thickness = 5;       // [2:1:12]
maze_floor_thickness = 2;      // [0:1:10]
maze_seed = 42;                // [1:1:200]
maze_wall_color = "DarkSlateGray";
maze_floor_color = "DimGray";
$fn = 24;

module maze(footprint, cells, wall_h, wall_t, floor_t, seed) {
  cell = footprint / cells;
  total_h = wall_h + floor_t;
  carve = rands(0, 1, cells * cells, seed);

  if (floor_t > 0) {
    color(maze_floor_color)
      cube([footprint, footprint, floor_t]);
  }

  color(maze_wall_color) {
    cube([footprint, wall_t, total_h]);
    translate([0, footprint - wall_t, 0])
      cube([footprint, wall_t, total_h]);
    translate([0, cell, 0])
      cube([wall_t, footprint - cell, total_h]);
    translate([footprint - wall_t, 0, 0])
      cube([wall_t, footprint - cell, total_h]);

    for (cx = [0 : cells - 1])
      for (cy = [0 : cells - 1]) {
        idx = cy * cells + cx;
        if (cx < cells - 1 && cy < cells - 1) {
          if (carve[idx] > 0.5) {
            translate([(cx + 1) * cell - wall_t / 2, cy * cell, 0])
              cube([wall_t, cell + wall_t, total_h]);
          } else {
            translate([cx * cell, (cy + 1) * cell - wall_t / 2, 0])
              cube([cell + wall_t, wall_t, total_h]);
          }
        }
      }
  }
}

maze(maze_footprint, maze_cells, maze_wall_height, maze_wall_thickness, maze_floor_thickness, maze_seed);
